  button.textContent = "Сагсанд хийх";

  cardEl.append(image, name, price, button);
  grid.append(cardEl);
});

const cart = [];

function addToCart(product) {
  const existing = cart.find(function (item) {
    return item.id === product.id;
  });

  if (existing) {
    existing.quantity += 1;
  } else {
    cart.push({ id: product.id, name: product.name, quantity: 1 });
  }

  renderCart();
}

function renderCart() {
  const list = document.querySelector('[data-testid="cart-items"]');
  list.textContent = "";

  let total = 0;
  cart.forEach(function (item) {
    total += item.quantity;
    const row = document.createElement("li");
    row.textContent = item.name + " × " + item.quantity;
    list.append(row);
  });

  document.querySelector('[data-testid="cart-count"]').textContent = String(total);
}

const buttons = document.querySelectorAll('[data-testid="add-to-cart"]');
buttons.forEach(function (button, index) {
  button.addEventListener("click", function () {
    addToCart(products[index]);
  });
});
